import { tags } from "typia";

/**
 * Simple numeric counts used on the user's dashboard. These are computed values
 * for the authenticated user's dashboard. Counts exclude soft-deleted rows
 * (records where deleted_at IS NOT NULL) and reflect current persisted data at
 * the time of computation. Field names use camelCase to align with API
 * conventions.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IUserDashboardCounts = {
  /**
   * Total number of lists owned by the user. Excludes soft-deleted lists
   * (deleted_at IS NOT NULL). Example: 5
   */
  totalLists: number & tags.Type<"int32">;

  /**
   * Number of lists where the user is an accepted collaborator (exclude
   * pending invites and soft-deleted lists). Example: 2
   */
  sharedListsCount: number & tags.Type<"int32">;

  /**
   * Total number of tasks across the user's owned lists. Excludes
   * soft-deleted tasks. Example: 42
   */
  totalTasks: number & tags.Type<"int32">;

  /**
   * Number of tasks that are due within the configured 'due soon' window
   * (typically next 7 days). Excludes completed and soft-deleted tasks.
   * Example: 3
   */
  dueSoonCount: number & tags.Type<"int32">;

  /**
   * Number of tasks completed within the recent reporting window (e.g., last
   * 7 days). Excludes soft-deleted tasks. Example: 10
   */
  recentCompletedCount: number & tags.Type<"int32">;
};
